    // Default: Crisp, high-end typographical vector logo in pure luxury white SVG
    default: {
      const len = brand.length;
      const fontSize = len <= 4 ? 30 : len <= 7 ? 24 : len <= 11 ? 20 : 17;
      const letterSpacing = len <= 4 ? 5 : len <= 7 ? 3.5 : len <= 11 ? 2.5 : 1.8;
      return (
        <svg
          viewBox="0 0 200 45"
          width={width ?? (typeof size === "number" ? Math.min(size * 1.55, 175) : size)}
          height={height ?? (typeof size === "number" ? size * 0.38 : size)}
          className={className}
          style={{ overflow: "visible", ...style }}
          aria-label={`${brand} logo`}
        >
          <text
            x="100"
            y="29"
            textAnchor="middle"
            fontFamily={
              norm.includes("la mer") ||
              norm.includes("prairie") ||
              norm.includes("guerlain") ||
              norm.includes("cucinelli") ||
              norm.includes("brioni") ||
              norm.includes("loropiana") ||
              norm.includes("zegna") ||
              norm.includes("canali") ||
              norm.includes("kiton") ||
              norm.includes("armani")
                ? "'Didot', 'Playfair Display', 'Bodoni MT', serif"
                : "'Century Gothic', 'Futura', 'Helvetica Neue', 'DM Sans', sans-serif"
            }
            fontSize={fontSize}
            fontWeight="700"
            letterSpacing={letterSpacing}
            fill={fill ?? "#ffffff"}
          >
            {brand.toUpperCase()}
          </text>
        </svg>
      );
    }
